    weights = [14, 7]
    total = sum(weights)
    n = len(weights)
    min_diff = total  # worst case
    # enumerate subsets using bitmask
    for mask in range(1 << n):
        subset_sum = 0
        for i in range(n):
            if mask & (1 << i):
