def solution() -> Tuple[List[int], int]:
    # Graph definition (directed)
    graph = {
        3: [(1, 4)],
        1: [(2, 4), (0, 5)],
        0: [(3, 1)],
        2: [(3, 1)],
    }
    start, target = 0, 3

    # Dijkstra's algorithm
    dist = {node: float('inf') for node in graph}
    prev = {}
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            break
        for v, w in graph.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    # Reconstruct path
    path: List[int] = []
    node = target
    while node != start:
        path.append(node)
        node = prev.get(node)
        if node is None:
            raise ValueError("No path found")
    path.append(start)
    path.reverse()
    total_distance = dist[target]
    return path, total_distance

