from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    # Graph definition (directed)
    # each entry: node -> list of (neighbor, weight)
    graph = {
        3: [(0, 1), (4, 6)],
        1: [(0, 1), (3, 7)],
        2: [(1, 7)],
        0: [(4, 1)],
        4: []
    }

    start, target = 0, 4
    # Dijkstra's algorithm
    dist = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        cur_dist, u = heapq.heappop(heap)
        if cur_dist > dist[u]:
            continue
        if u == target:
            break
        for v, w in graph[u]:
            alt = cur_dist + w
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heapq.heappush(heap, (alt, v))

    # Reconstruct path
    path: List[int] = []
    node = target
    if dist[target] == float('inf'):
        # No path found
        return ([], -1)
    while node is not None:
        path.append(node)
        node = prev[node]
    path.reverse()
    return (path, int(dist[target]))

