        (5, 2, 8),
        (5, 0, 1),
        (5, 4, 5),
    ]
    graph = {}
    for u, v, w in edges:
        graph.setdefault(u, []).append((v, w))
        graph.setdefault(v, []).append((u, w))  # undirected

    start, target = 0, 5
    # Dijkstra's algorithm
    heap = [(0, start, [start])]
    visited = {}
    while heap:
        dist, node, path = heapq.heappop(heap)
        if node in visited and visited[node] <= dist:
