def solution():
    from itertools import combinations
    weights = [5, 3, 4, 2, 4]
    values = [1, 5, 1, 5, 2]
    capacity = 25
    n = len(weights)
    best_val = 0
    best_set = []
    # examine every possible subset
    for r in range(n + 1):
        for idxs in combinations(range(n), r):
            w_sum = sum(weights[i] for i in idxs)
            if w_sum <= capacity:
                v_sum = sum(values[i] for i in idxs)
                if v_sum > best_val:
                    best_val = v_sum
                    best_set = list(idxs)
    feasible = best_val > 0
    return (feasible, best_val, best_set)

